import{_ as e,o as n,c as r,a2 as i}from"./chunks/framework.CPzUcv0I.js";const h=JSON.parse('{"title":"Horizon Cloud Sync (Player Guide)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/players/cloud-sync.md","filePath":"guide/players/cloud-sync.md"}'),a={name:"guide/players/cloud-sync.md"};function t(s,o,l,c,d,u){return n(),r("div",null,[...o[0]||(o[0]=[i('<h1 id="horizon-cloud-sync-player-guide" tabindex="-1">Horizon Cloud Sync (Player Guide) <a class="header-anchor" href="#horizon-cloud-sync-player-guide" aria-label="Permalink to &quot;Horizon Cloud Sync (Player Guide)&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Technology-Delta%20Sync-blue.svg" alt="Delta Sync"><img src="https://img.shields.io/badge/Providers-Google%20Drive%20%7C%20Dropbox%20%7C%20OneDrive-green.svg" alt="Providers"><img src="https://img.shields.io/badge/Encryption-AES--256--GCM-red.svg" alt="Encryption"></div><p>The <strong>Horizon Cloud Sync</strong> technology is a marquee innovation in Gens Launcher. It enables you to automatically synchronize your Minecraft instances (singleplayer worlds, keybindings, inventories, resource packs, and mods) across multiple computers using your own personal cloud storage.</p><hr><h2 id="how-does-cloud-sync-work" tabindex="-1">How Does Cloud Sync Work? <a class="header-anchor" href="#how-does-cloud-sync-work" aria-label="Permalink to &quot;How Does Cloud Sync Work?&quot;">​</a></h2><p>Unlike traditional tools that re-upload an entire 500 MB game directory each time you play, Gens-Horizon utilizes differential synchronization (<strong>Delta Sync</strong>):</p><ul><li>Only files modified since your last session are processed.</li><li>Unaltered files are never re-transferred over the network.</li><li>An average gaming session consumes only a few megabytes of bandwidth and syncs in mere seconds.</li></ul><hr><h2 id="connecting-a-cloud-provider" tabindex="-1">Connecting a Cloud Provider <a class="header-anchor" href="#connecting-a-cloud-provider" aria-label="Permalink to &quot;Connecting a Cloud Provider&quot;">​</a></h2><ol><li>Open <strong>Settings</strong> in Gens Launcher -&gt; switch to the <strong>Horizon Cloud</strong> tab.</li><li>Choose your preferred storage provider: <ul><li><strong>Google Drive</strong></li><li><strong>Dropbox</strong></li><li><strong>Microsoft OneDrive</strong></li></ul></li><li>Click <strong>Connect</strong>. A secure official authentication page will open in your web browser.</li><li>Grant access permissions to the application. Gens-Horizon encrypts access tokens locally on your disk using a hardware-bound key (<strong>PBKDF2</strong> with 600,000 iterations + <strong>AES-256-GCM</strong>).</li><li>Once connected, your remaining storage quota is displayed directly in the launcher interface.</li></ol><hr><h2 id="enabling-synchronization-on-an-instance" tabindex="-1">Enabling Synchronization on an Instance <a class="header-anchor" href="#enabling-synchronization-on-an-instance" aria-label="Permalink to &quot;Enabling Synchronization on an Instance&quot;">​</a></h2><ol><li>Right-click any instance -&gt; <strong>Instance Settings</strong>.</li><li>Check the box <strong>Enable Horizon Cloud Sync</strong>.</li><li>Select your sync strategy: <ul><li><strong>Smart Sync (Recommended):</strong> Gens Launcher verifies whether a newer remote save exists before starting the game, and automatically uploads modifications when you quit playing.</li><li><strong>Manual Mode:</strong> You trigger upload or restore actions on demand using the <em>Upload to Cloud</em> and <em>Restore from Cloud</em> buttons.</li></ul></li></ol><hr><h2 id="version-history-and-rollback" tabindex="-1">Version History and Rollback <a class="header-anchor" href="#version-history-and-rollback" aria-label="Permalink to &quot;Version History and Rollback&quot;">​</a></h2><p>If a game world becomes corrupted or a buggy mod damages your save data:</p><ol><li>Open the instance&#39;s <strong>Cloud</strong> tab.</li><li>Review the chronological history of past sessions and snapshots.</li><li>Click <strong>Rollback to this point</strong> to restore the exact state of your instance files at that point in time.</li></ol><hr><h2 id="data-privacy-and-security" tabindex="-1">Data Privacy and Security <a class="header-anchor" href="#data-privacy-and-security" aria-label="Permalink to &quot;Data Privacy and Security&quot;">​</a></h2><ul><li><strong>Your Personal Storage:</strong> Backups are hosted exclusively on your personal cloud account (Google Drive, Dropbox, or OneDrive). No third-party servers store your files.</li><li><strong>Atomic Lockfile Protection:</strong> If your game is currently running on one PC, an atomic lockfile (<code>horizon.lock</code>) prevents conflicting writes or accidental overwrites from a second computer.</li></ul>',20)])])}const y=e(a,[["render",t]]);export{h as __pageData,y as default};
